baec_engine1.julianday(text):
DECLARE
    m text[];
    y int; mo int; d int; h int := 0; mi int := 0; s double precision := 0;
    frac double precision := 0; scale double precision := 1; i int;
    a int; b int; x1 int; x2 int; tz int := 0;
    jd bigint;
BEGIN
    m := pg_catalog.regexp_match($1, '^([0-9]{4})-([0-9]{2})-([0-9]{2})[[:space:]T]*(?:([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?[[:space:]]*(?:([Zz])|([+-])([0-9]{2}):([0-9]{2}))?[[:space:]]*)?$');
    IF m IS NULL THEN
        RETURN NULL;
    END IF;
    y := m[1]::int; mo := m[2]::int; d := m[3]::int;
    IF mo < 1 OR mo > 12 OR d < 1 OR d > 31 THEN
        RETURN NULL;
    END IF;
    IF m[4] IS NOT NULL THEN
        h := m[4]::int; mi := m[5]::int;
        IF h > 24 OR mi > 59 THEN
            RETURN NULL;
        END IF;
        IF m[6] IS NOT NULL THEN
            s := m[6]::int;
            IF s > 59 THEN
                RETURN NULL;
            END IF;
            IF m[7] IS NOT NULL THEN
                FOR i IN 1 .. pg_catalog.length(m[7]) LOOP
                    frac := frac * 10 + pg_catalog.substr(m[7], i, 1)::int;
                    scale := scale * 10;
                END LOOP;
                frac := frac / scale;
                IF frac > 0.999 THEN
                    frac := 0.999;
                END IF;
                s := s + frac;
            END IF;
        END IF;
    END IF;
    IF m[9] IS NOT NULL THEN
        IF m[10]::int > 14 OR m[11]::int > 59 THEN
            RETURN NULL;
        END IF;
        tz := m[10]::int * 60 + m[11]::int;
        IF m[9] = '-' THEN
            tz := -tz;
        END IF;
    END IF;
    IF mo <= 2 THEN
        y := y - 1;
        mo := mo + 12;
    END IF;
    a := (y + 4800) / 100;
    b := 38 - a + (a / 4);
    x1 := 36525 * (y + 4716) / 100;
    x2 := 306001 * (mo + 1) / 10000;
    jd := pg_catalog.trunc((x1 + x2 + d + b - 1524.5::double precision) * 86400000)::bigint;
    IF m[4] IS NOT NULL THEN
        jd := jd + h * 3600000 + mi * 60000 + pg_catalog.trunc(s * 1000 + 0.5)::bigint - tz * 60000;
    END IF;
    RETURN jd / 86400000.0::double precision;
END

baec_engine1.refuse_replace():
DECLARE
    collisions text := '';
    condition text;
    key_column text;
    found boolean;
    i int;
BEGIN
    PERFORM baec_engine1.lock_workspace(NEW.organization_id, NEW.workspace);
    FOR i IN 0 .. TG_NARGS - 1 LOOP
        condition := 'organization_id = ($1).organization_id AND workspace = ($1).workspace';
        FOREACH key_column IN ARRAY pg_catalog.string_to_array(TG_ARGV[i], ',') LOOP
            IF pg_catalog.left(key_column, 1) = '#' THEN
                condition := condition || pg_catalog.format(' AND %I = COALESCE(($1).%I, -1)',
                                                            pg_catalog.substr(key_column, 2),
                                                            pg_catalog.substr(key_column, 2));
            ELSE
                condition := condition || pg_catalog.format(' AND %I = ($1).%I', key_column, key_column);
            END IF;
        END LOOP;
        collisions := collisions || CASE WHEN i = 0 THEN '' ELSE ' OR ' END
            || pg_catalog.format('EXISTS (SELECT 1 FROM baec_engine1.%I WHERE %s)', TG_TABLE_NAME, condition);
    END LOOP;
    EXECUTE 'SELECT ' || collisions INTO found USING NEW;
    IF found THEN
        RAISE EXCEPTION '% rows cannot be replaced', TG_TABLE_NAME USING ERRCODE = 'unique_violation';
    END IF;
    RETURN NEW;
END

baec_engine2.assign_event_id():
BEGIN
    IF NEW.event_id IS NULL THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
            'baec_engine2.audit_events/' || NEW.organization_id || '/' || NEW.workspace, 0));
        SELECT COALESCE(max(e.event_id), 0) + 1 INTO NEW.event_id FROM baec_engine2.audit_events e
        WHERE e.organization_id = NEW.organization_id AND e.workspace = NEW.workspace;
    END IF;
    RETURN NEW;
END

baec_engine2.refuse_meta_replace():
BEGIN
    IF EXISTS (SELECT 1 FROM baec_engine2.engine2_meta m WHERE m.key = NEW.key) THEN
        RAISE EXCEPTION '% rows cannot be replaced', TG_TABLE_NAME USING ERRCODE = 'unique_violation';
    END IF;
    RETURN NEW;
END

baec_engine2.refuse_replace():
DECLARE
    condition text := 'organization_id = ($1).organization_id AND workspace = ($1).workspace';
    found boolean;
    i int;
BEGIN
    FOR i IN 0 .. TG_NARGS - 1 LOOP
        condition := condition || format(' AND %I = ($1).%I', TG_ARGV[i], TG_ARGV[i]);
    END LOOP;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM baec_engine2.%I WHERE %s)', TG_TABLE_NAME, condition)
        INTO found USING NEW;
    IF found THEN
        RAISE EXCEPTION '% rows cannot be replaced', TG_TABLE_NAME USING ERRCODE = 'unique_violation';
    END IF;
    RETURN NEW;
END

baec_engine2.require_activation():
BEGIN
    IF COALESCE((SELECT a.result FROM baec_engine2.plan_activations a
                 WHERE a.organization_id = NEW.organization_id AND a.workspace = NEW.workspace
                   AND a.activation_id = NEW.activation_id), '') <> 'ACTIVATED' THEN
        RAISE EXCEPTION '% requires an ACTIVATED Monitoring Plan', TG_TABLE_NAME USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
